// Retell AI sendet: { args: { patient_name, slot_start, patient_phone, prescription, new_patient } }
const args = $input.first().json.body?.args || $input.first().json.args || {};

const patientName = args.patient_name || '';
const patientPhone = args.patient_phone || '';
const slotStart = args.slot_start || '';
const prescription = args.prescription;
const newPatient = args.new_patient;
const reason = args.reason || args.service || args.leistung || 'Nicht angegeben';

// Validierung
if (!patientName || !patientPhone || !slotStart) {
  return [{ json: { valid: false, error: 'patient_name, patient_phone und slot_start sind Pflichtfelder.' } }];
}

// slot_end = slot_start + 20 Minuten
const startDate = new Date(slotStart);
const endDate = new Date(startDate.getTime() + 20 * 60 * 1000);
const slotEnd = endDate.toISOString();

// Datum in Berliner Zeit formatieren für SMS/E-Mail
const berlinOptions = { timeZone: 'Europe/Berlin' };
const dayNames = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];
const berlinDay = new Date(startDate.toLocaleString('en-US', berlinOptions));
const day = dayNames[berlinDay.getDay()];
const dd = String(berlinDay.getDate()).padStart(2, '0');
const mm = String(berlinDay.getMonth() + 1).padStart(2, '0');
const yyyy = berlinDay.getFullYear();
const hh = String(berlinDay.getHours()).padStart(2, '0');
const min = String(berlinDay.getMinutes()).padStart(2, '0');
const formattedDate = `${day}, ${dd}.${mm}.${yyyy} um ${hh}:${min} Uhr`;

// prescription: normalize to boolean
const prescriptionRaw = String(prescription ?? '').toLowerCase().trim();
const hasPrescription = [true, 'true', 'verordnung', 'ja', 'yes'].includes(prescription) || ['true', 'verordnung', 'ja', 'yes'].includes(prescriptionRaw);
const prescriptionText = hasPrescription ? 'Verordnung' : 'Selbstzahler';

return [{
  json: {
    valid: true,
    patient_name: patientName,
    patient_phone: patientPhone,
    slot_start: slotStart,
    slot_end: slotEnd,
    reason: reason,
    prescription: prescriptionText,
    new_patient: newPatient ?? true,
    formatted_date: formattedDate
  }
}];
